import { createRouter, createWebHistory, type RouteRecordRaw, type NavigationGuardNext, type RouteLocationNormalized } from 'vue-router'
import { useAuthStore } from '@stores/useAuthStore'

const routes: RouteRecordRaw[] = [
  {
    path: '/login',
    name: 'Login',
    component: () => import('@views/LoginView.vue'),
    meta: { requiresAuth: false, title: 'Anmelden' },
  },
  {
    path: '/join/:code?',
    name: 'Join',
    component: () => import('@views/LoginView.vue'),
    meta: { requiresAuth: false, title: 'Beitreten' },
  },
  {
    path: '/voice',
    name: 'Voice',
    component: () => import('@views/VoiceView.vue'),
    meta: { requiresAuth: true, title: 'Sprachchat' },
  },
  {
    path: '/settings',
    name: 'Settings',
    component: () => import('@views/SettingsView.vue'),
    meta: { requiresAuth: true, title: 'Einstellungen' },
  },
  {
    path: '/:pathMatch(.*)*',
    redirect: '/voice',
  },
]

const BASE_URL = import.meta.env?.BASE_URL || '/'

const router = createRouter({
  history: createWebHistory(BASE_URL),
  routes,
})

router.beforeEach((
  to: RouteLocationNormalized,
  from: RouteLocationNormalized,
  next: NavigationGuardNext
) => {
  const requiresAuth = to.matched.some(record => record.meta['requiresAuth'])
  const authStore = useAuthStore()

  if (requiresAuth && !authStore.isAuthenticated) {
    next({ name: 'Login', query: { redirect: to.fullPath } })
  } else if ((to.name === 'Login' || to.name === 'Join') && authStore.isAuthenticated && !to.params['code']) {
    // Allow authenticated users to access /join/:code for joining with a code
    // But redirect from /login or /join (without code) to /voice
    next({ name: 'Voice' })
  } else {
    next()
  }
})

export default router
